import re
from typing import Dict, Any


def get_assert(output: str, context: Dict[str, Any]) -> Dict[str, Any]:
    if not context["vars"].get("matches"):
        return {
            "pass": True,
            "score": 1,
            "reason": "No matches regex provided, nothing to validate.",
        }

    pattern = re.compile(context["vars"]["matches"], re.DOTALL | re.MULTILINE)
    pass_test = bool(pattern.search(output))

    return {
        "pass": pass_test,
        "score": 1 if pass_test else 0,
        "reason": f'Output matches regex "{context["vars"]["matches"]}"'
        if pass_test
        else f'Expected output to match regex "{context["vars"]["matches"]}"',
    }
